import { DomainError } from "./domain-error";

export const FULFILMENT_FLOW = ["placed", "paid", "packed", "shipped", "delivered"] as const;

export type FulfilmentStatus = (typeof FULFILMENT_FLOW)[number];
export type OrderStatus = FulfilmentStatus | "cancelled";

export const ORDER_STATUSES: readonly OrderStatus[] = [...FULFILMENT_FLOW, "cancelled"];

export function isOrderStatus(value: unknown): value is OrderStatus {
  return typeof value === "string" && (ORDER_STATUSES as readonly string[]).includes(value);
}

export function nextFulfilmentStatus(current: OrderStatus): FulfilmentStatus | undefined {
  if (current === "cancelled") return undefined;
  return FULFILMENT_FLOW[FULFILMENT_FLOW.indexOf(current) + 1];
}

export function isCancellable(current: OrderStatus): boolean {
  return current === "placed" || current === "paid" || current === "packed";
}

export function assertOrderStatus(status: unknown): asserts status is OrderStatus {
  if (!isOrderStatus(status)) {
        throw new DomainError("VALIDATION", "Query parameter 'status' must be a valid order status");
      }
}

